        "EndpointSlice" => [ # k8s.io/kubernetes/pkg/apis/discovery
          {"name" => "Name", "type" => "string", "format" => "name", "description" => "Name must be unique within a namespace. Is required when creating resources, although some resources may allow a client to request the generation of an appropriate name automatically. Name is primarily intended for creation idempotence and configuration definition. Cannot be updated. More info: https://kubernetes.io/docs/concepts/overview/working-with-objects/names#names", "priority" => 0}.freeze,
          {"name" => "AddressType", "type" => "string", "format" => "", "description" => "addressType specifies the type of address carried by this EndpointSlice. All addresses in this slice must be the same type. This field is immutable after creation. The following address types are currently supported: * IPv4: Represents an IPv4 Address. * IPv6: Represents an IPv6 Address. * FQDN: Represents a Fully Qualified Domain Name. (Deprecated) The EndpointSlice controller only generates, and kube-proxy only processes, slices of addressType \"IPv4\" and \"IPv6\". No semantics are defined for the \"FQDN\" type.", "priority" => 0}.freeze,
          {"name" => "Ports", "type" => "string", "format" => "", "description" => "ports specifies the list of network ports exposed by each endpoint in this slice. Each port must have a unique name. Each slice may include a maximum of 100 ports. Services always have at least 1 port, so EndpointSlices generated by the EndpointSlice controller will likewise always have at least 1 port. EndpointSlices used for other purposes may have an empty ports list.", "priority" => 0}.freeze,
          {"name" => "Endpoints", "type" => "string", "format" => "", "description" => "endpoints is a list of unique endpoints in this slice. Each slice may include a maximum of 1000 endpoints.", "priority" => 0}.freeze,
