        "FlowSchema" => [ # k8s.io/kubernetes/pkg/apis/flowcontrol
          {"name" => "Name", "type" => "string", "format" => "name", "description" => "Name must be unique within a namespace. Is required when creating resources, although some resources may allow a client to request the generation of an appropriate name automatically. Name is primarily intended for creation idempotence and configuration definition. Cannot be updated. More info: https://kubernetes.io/docs/concepts/overview/working-with-objects/names#names", "priority" => 0}.freeze,
          {"name" => "PriorityLevel", "type" => "string", "format" => "", "description" => "`name` is the name of the priority level configuration being referenced Required.", "priority" => 0}.freeze,
          {"name" => "MatchingPrecedence", "type" => "string", "format" => "", "description" => "`matchingPrecedence` is used to choose among the FlowSchemas that match a given request. The chosen FlowSchema is among those with the numerically lowest (which we take to be logically highest) MatchingPrecedence.  Each MatchingPrecedence value must be ranged in [1,10000]. Note that if the precedence is not specified, it will be set to 1000 as default.", "priority" => 0}.freeze,
          {"name" => "DistinguisherMethod", "type" => "string", "format" => "", "description" => "`distinguisherMethod` defines how to compute the flow distinguisher for requests that match this schema. `nil` specifies that the distinguisher is disabled and thus will always be the empty string.", "priority" => 0}.freeze,
          {"name" => "Age", "type" => "string", "format" => "", "description" => "CreationTimestamp is a timestamp representing the server time when this object was created. It is not guaranteed to be set in happens-before order across separate operations. Clients may not set this value. It is represented in RFC3339 form and is in UTC.\n\nPopulated by the system. Read-only. Null for lists. More info: https://git.k8s.io/community/contributors/devel/sig-architecture/api-conventions.md#metadata", "priority" => 0}.freeze,
          {"name" => "MissingPL", "type" => "string", "format" => "", "description" => "references a broken or non-existent PriorityLevelConfiguration", "priority" => 0}.freeze,
